'use strict';
const M=StillModel,P=M.products,$=s=>document.querySelector(s),main=$('#main'),sheet=$('#sheet'),body=$('#sheet-body'),native=!!window.StillAndroid;
let state,storageError='',page='now',selectedDay=M.day(),month=new Date(new Date().getFullYear(),new Date().getMonth(),1),photoPending=null,stream=null,photoCallback=null,renderTick,toastTick,savingRemoval=false;
const safe=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
try{const raw=native?StillAndroid.getState():localStorage.getItem('still-in-v1');state=raw?M.validate(JSON.parse(raw)):M.blank()}catch(e){state=M.blank();storageError='Saved data could not be read. Reload the app before making changes.'}
const time=ts=>new Date(ts).toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'}),dateLabel=d=>new Date(d+'T12:00:00').toLocaleDateString([],{weekday:'long',day:'numeric',month:'long'}),durationText=ms=>{const m=Math.floor(ms/60000);return `${Math.floor(m/60)}h ${m%60}m`},id=()=>crypto.randomUUID();
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(toastTick);toastTick=setTimeout(()=>$('#toast').classList.remove('show'),3600)}
function save(){if(storageError)throw Error(storageError);const raw=JSON.stringify(state);if(native){const r=StillAndroid.saveState(raw);if(r!=='ok')throw Error(r||'Could not save. Try again.')}else localStorage.setItem('still-in-v1',raw)}
function transaction(fn){const before=JSON.stringify(state);try{const result=fn();save();return result}catch(e){state=JSON.parse(before);throw e}}
function doAction(fn){try{fn()}catch(e){toast(e.message)}}
const eye='<circle cx="39" cy="43" r="2.4" fill="#36151f"/><circle cx="57" cy="43" r="2.4" fill="#36151f"/><path d="M43 51q5 5 10 0" fill="none" stroke="#36151f" stroke-width="2.3" stroke-linecap="round"/><ellipse cx="32" cy="49" rx="4" ry="2" fill="#ee9db4"/><ellipse cx="64" cy="49" rx="4" ry="2" fill="#ee9db4"/>';
function art(type,soak=0,sleep=false){const fill=['#fff9f7','#f5ceda','#ed9db8','#d9638b','#b93662'][soak],stroke='#78253b';let shape='';if(type==='tampon')shape=`<path d="M36 65V24a12 12 0 0124 0v41q0 8-12 8T36 65" fill="${fill}" stroke="${stroke}" stroke-width="2.8"/><path d="M43 21v11m10-11v11M48 73q15 8 3 15" fill="none" stroke="${stroke}" stroke-width="2.8" stroke-linecap="round"/>`;
else if(type==='cup')shape=`<path d="M20 23h56l-7 34q-4 16-21 16T27 57z" fill="#d85c74" stroke="${stroke}" stroke-width="2.8"/><path d="M29 56q19-8 38 0l-2 7q-17 19-34 0z" fill="#b93655"/><rect x="18" y="18" width="60" height="9" rx="4.5" fill="#ffacb9" stroke="${stroke}" stroke-width="2.8"/><path d="M48 74v10" stroke="${stroke}" stroke-width="5" stroke-linecap="round"/>`;
else if(type==='disc')shape=`<ellipse cx="48" cy="46" rx="35" ry="21" fill="#bc727e" stroke="#7e3544" stroke-width="2.8"/><path d="M14 44q0 31 34 31t34-31" fill="#ad5468" stroke="#7e3544" stroke-width="2.8"/><ellipse cx="48" cy="41" rx="34" ry="18" fill="#f0b8c4" stroke="#7e3544" stroke-width="3"/><path d="M26 36q9-8 23-8" stroke="white" stroke-width="4" stroke-linecap="round" fill="none"/>`;
else if(type==='pad'||type==='liner')shape=`<path d="M33 22q-4-13 15-13t15 13l-3 15q17-2 17 9t-17 8l3 17q4 15-15 15T33 71l3-17q-17 3-17-8t17-9z" fill="#ae7b88" stroke="${stroke}" stroke-width="2.5"/><rect x="34" y="18" width="28" height="60" rx="14" fill="${fill}" stroke="${stroke}" stroke-width="1.6"/>`;
else if(type==='pants')shape=`<path d="M10 23h76l-6 29q-14 3-22 24H38q-8-21-22-24z" fill="#c85069" stroke="#7d293e" stroke-width="2.8"/><path d="M11 28h74M32 30q2 32 8 44m24-44q-2 32-8 44" fill="none" stroke="#f8b6c7" stroke-width="4"/>`;
return `<svg class="product-art" viewBox="0 0 96 96" aria-hidden="true">${shape}${sleep?'<path d="M36 44q4 4 8 0m9 0q4 4 8 0" stroke="#36151f" stroke-width="2.4" fill="none" stroke-linecap="round"/><text x="72" y="18" fill="#ff7688" font-size="16" font-weight="bold">z</text>':eye}</svg>`}
function drop(flow){const fills={none:'#4a3841',spotting:'#9b5366',light:'#c35875',medium:'#e04c71',heavy:'#f32f58'};return `<svg viewBox="0 0 30 36" aria-hidden="true"><path d="M15 2C13 9 3 16 3 23a12 12 0 0024 0C27 16 17 9 15 2Z" fill="${fills[flow]}"/><path d="M8 23q0 6 5 7" fill="none" stroke="#fff9" stroke-width="2.5" stroke-linecap="round"/>${flow==='none'?'<path d="M6 29L24 11" stroke="#baa1ad" stroke-width="2"/>':''}</svg>`}
const flows=['none','spotting','light','medium','heavy'];
function flowUI(day){const chosen=state.days[day]?.flow;return `<div class="flow-options">${flows.map(f=>`<button class="flow-option ${chosen===f?'selected':''}" data-flow="${f}" data-day="${day}" aria-pressed="${chosen===f}">${drop(f)}${f==='none'?'No blood':f[0].toUpperCase()+f.slice(1)}</button>`).join('')}</div>`}
function setupStatus(){if(!native)return null;try{return JSON.parse(StillAndroid.status())}catch(e){return {notifications:false,exact:false}}}
function warning(){if(!native)return `<div class="native-warning"><strong>Meet your new period sidekick.</strong><br>Try the draft here. Phone alarms work in the Android app.<br><a class="btn secondary" href="still-in-0.2.apk" download>↓ Get the Android app</a></div>`;const s=setupStatus();return !s.notifications||!s.exact?`<div class="native-warning"><strong>${!s.notifications?'Phone reminders are off':'Precise alarms need permission'}</strong><br>${!s.notifications?'Allow notifications to get removal reminders.':'Your reminders may arrive late until this is enabled.'}<br><button class="btn secondary" data-setup>Set up reminders</button></div>`:''}
function render(){clearInterval(renderTick);document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.page===page));if(page==='now')renderNow();if(page==='calendar')renderCalendar();if(page==='history')renderHistory();bind();if(page==='now')renderTick=setInterval(updateTimers,1000);updateTimers()}
function renderNow(){const today=M.day();let active=[...state.active].sort((a,b)=>a.due-b.due);let night=state.days[today]?.nothingTonight;main.innerHTML=`<div class="eyebrow">${new Date().toLocaleDateString([],{weekday:'long',day:'numeric',month:'short'})}</div><h1>What's the situation?</h1>${storageError?`<p class="error">${safe(storageError)}</p>`:''}${warning()}${active.length?active.map((x,i)=>i===0?`<section class="card hero" data-timer="${x.id}"><div class="row hero-top"><h2>${P[x.type].name}${P[x.type].internal?' is in.':' is on.'}</h2><span class="badge">${P[x.type].internal?'Currently occupied':'On duty'}</span></div><div class="dial"><svg viewBox="0 0 240 240" aria-hidden="true"><circle class="dial-bg" cx="120" cy="120" r="112" fill="none" stroke-width="7"/><circle class="dial-line" cx="120" cy="120" r="112" fill="none" stroke-width="7" stroke-dasharray="703.72"/></svg><div class="dial-inner">${art(x.type)}<div class="time" data-countdown></div><div class="timer-label" data-timer-label>until it's out</div></div></div><div class="time-stamps"><div>${P[x.type].internal?'Put in':'Put on'}<strong>${time(x.start)}</strong></div><div>Due out<strong>${time(x.due)}</strong></div></div><button class="btn highlight full" data-remove="${x.id}">${P[x.type].verb} <span aria-hidden="true">✓</span></button></section>`:`<section class="card small-card" data-timer="${x.id}">${art(x.type)}<div class="grow"><h3>${P[x.type].name}${P[x.type].internal?' is in':' is on'}</h3><span class="caption" data-countdown></span><span class="caption" data-timer-label></span></div><button class="btn secondary" data-remove="${x.id}">${P[x.type].verb}</button></section>`).join(''):`<section class="card empty"><span class="badge">${night?'Off duty tonight':'All clear down there'}</span><div>${art('cup',0,true)}</div><h2>${night&&state.settings.cheeky?'No backup. Brave.':'Nothing in. Nothing on.'}</h2><p class="caption">${night?(state.settings.cheeky?'The sheets wish you luck.':'Logged for tonight. Rest well.'):(state.settings.cheeky?'An unoccupied establishment. What are we working with?':'Choose what you’re using below.')}</p><button class="btn full" data-choose>＋ ${night?'Changed your mind?':'Log a product'}</button></section>`}<div class="row section-title"><h2>${active.length?'Add a little backup':'Pick your protection'}</h2><span class="caption">Tap to log</span></div><div class="product-grid">${Object.keys(P).map(k=>`<button class="product-btn" data-add="${k}">${art(k)}${P[k].name}</button>`).join('')}</div><section class="card flow-card spaced"><div class="row"><h2>Today's flow</h2><button class="plain-link" data-calendar>Calendar</button></div>${flowUI(today)}</section>${!active.length&&!night?`<button class="btn outline full" data-nothing>☾ Nothing tonight</button>`:''}<div class="tip spaced"><span>✦</span><div>${state.settings.cheeky?'You remember everything else. Let us remember the tampon.':'Your logs stay on this device. No account needed.'}</div></div>`}
function updateTimers(){for(const x of state.active){const el=document.querySelector(`[data-timer="${x.id}"]`);if(!el)continue;const t=M.timer(x),seconds=Math.floor(t.ms/1000),h=String(Math.floor(seconds/3600)).padStart(2,'0'),m=String(Math.floor(seconds%3600/60)).padStart(2,'0'),s=String(seconds%60).padStart(2,'0');el.classList.toggle('overdue',t.overdue);el.querySelector('[data-countdown]').textContent=`${h}:${m}:${s}`;el.querySelector('[data-timer-label]').textContent=t.overdue?' overdue — time to change':(P[x.type].internal?' until it’s out':' until a change');const line=el.querySelector('.dial-line');if(line)line.style.strokeDashoffset=703.72*t.progress;}}
function renderCalendar(){const y=month.getFullYear(),m=month.getMonth(),offset=(new Date(y,m,1).getDay()+6)%7,count=new Date(y,m+1,0).getDate(),today=M.day();main.innerHTML=`<div class="eyebrow">The actual dates</div><h1>Your calendar.</h1><section class="card"><div class="calendar-head"><button class="icon-button" data-month="-1" aria-label="Previous month">‹</button><h2>${month.toLocaleDateString([],{month:'long',year:'numeric'})}</h2><button class="icon-button" data-month="1" aria-label="Next month">›</button></div><div class="calendar-grid">${['M','T','W','T','F','S','S'].map(d=>`<div class="weekday">${d}</div>`).join('')}${'<div></div>'.repeat(offset)}${Array.from({length:count},(_,i)=>{const d=M.day(new Date(y,m,i+1)),flow=state.days[d]?.flow,logs=state.history.filter(x=>M.day(x.end)===d).length;return `<button class="day ${d===selectedDay?'selected':''} ${d===today?'today':''}" ${flow?`data-flow="${flow}"`:''} data-date="${d}" aria-label="${dateLabel(d)}, ${flow||'not logged'}${logs?', '+logs+' product logs':''}">${i+1}<span class="mini">${logs?'•':''}</span></button>`}).join('')}</div><div class="legend">${flows.slice(1).map((f,i)=>`<span><i style="background:${['#332027','#612435','#99314a','#c72d4e'][i]}"></i>${f[0].toUpperCase()+f.slice(1)}</span>`).join('')}</div></section><section class="card flow-card"><div class="row"><h3>${dateLabel(selectedDay)}</h3>${state.days[selectedDay]?.flow?'<button class="plain-link" data-clear-flow>Clear</button>':''}</div>${selectedDay>today?'<p class="caption">Future date. Log your flow when the day arrives.</p>':flowUI(selectedDay)}<div class="field"><label for="day-note">Anything to remember? <span class="muted">Optional</span></label><textarea id="day-note" maxlength="1000" rows="2" placeholder="Spotting, leaked, cramps…">${safe(state.days[selectedDay]?.note||'')}</textarea></div><button class="btn secondary full" data-save-note>Save note</button></section>${state.days[selectedDay]?.nothingTonight?'<p class="caption">☾ No protection overnight</p>':''}${historyRows(state.history.filter(x=>M.day(x.end)===selectedDay))}<div class="footer-note">Only what you log. No cycle guesses or predictions.<br>Blank days mean unlogged, not blood-free.</div>`}
function historyRows(logs){return logs.map(x=>`<div class="history-row">${art(x.type,x.soak??0)}<div class="history-text"><strong>${P[x.type].name}</strong><div class="caption">${time(x.start)} – ${time(x.end)} · ${durationText(x.end-x.start)}</div><div class="caption">${x.soak===null||x.soak===undefined?'':['Dry','A little soaked','Half soaked','Mostly soaked','Fully soaked'][x.soak]}${x.leaked?' · Leaked':''}${x.reinserted?' · Emptied + back in':''}</div>${x.photo?`<button class="receipt-photo" data-view-photo="${safe(x.photo)}">▧ View private photo</button>`:''}</div><div class="amount">${x.ml!==null&&x.ml!==undefined?`${x.ml} ml`:''}</div><button class="icon-button" data-log="${x.id}" aria-label="View ${P[x.type].name} log">⋯</button></div>`).join('')}
function renderHistory(){let days=[...new Set(state.history.map(x=>M.day(x.end)))];let collected=state.history.reduce((s,x)=>s+(x.ml??0),0);main.innerHTML=`<div class="eyebrow">The evidence</div><h1>The receipts.</h1><div class="stats"><div class="stat"><strong>${state.history.length}</strong><small>Product changes</small></div><div class="stat"><strong>${collected}<span style="font-size:16px"> ml</span></strong><small>Collected & logged</small></div></div>${days.length?days.map(d=>`<div class="history-date">${dateLabel(d)}</div><div>${historyRows(state.history.filter(x=>M.day(x.end)===d))}</div>`).join(''):`<section class="empty-history">${art('tampon')}<h2>No receipts. Yet.</h2><p class="caption">Your product changes will land here.<br>Photos stay hidden until you tap to view.</p></section>`}<div class="footer-note">Collected volume is what you enter for cups and discs.<br>Tampon / pad saturation is logged separately.</div>`}
function show(content){body.innerHTML=content;if(!sheet.open)sheet.showModal();bindSheet()}
function head(title){return `<div class="sheet-head"><h2>${title}</h2><button class="icon-button" data-close aria-label="Close">×</button></div>`}
function closeSheet(){if(savingRemoval)return;if(stream){stream.getTracks().forEach(t=>t.stop());stream=null}sheet.close();photoCallback=null}
function choose(){show(head('What are you using?')+`<div class="product-grid">${Object.keys(P).map(k=>`<button class="product-btn" data-add="${k}">${art(k)}${P[k].name}</button>`).join('')}</div>`)}
function openAdd(type){if(state.active.some(x=>x.type===type)){toast('Already wearing one — log its removal first.');return}if(P[type].internal&&state.active.some(x=>P[x.type].internal)){toast('Take out your current internal product first.');return}let hours=state.settings.hours[type]||P[type].hours;show(head(P[type].internal?'Going in?':'Going on?')+`<form id="add-form"><div class="product-intro">${art(type)}<div><h3>${P[type].name}</h3><span class="caption">${P[type].internal?'A little occupied.':'Backup has arrived.'}</span></div></div><div class="field"><label for="start-time">${P[type].internal?'Put in':'Put on'}</label><input id="start-time" type="datetime-local" required value="${localInput(Date.now())}" max="${localInput(Date.now())}"></div><div class="field"><label>Remind me after</label><div class="chips">${[2,4,6,8,10,12].filter(h=>h<=P[type].max).map(h=>`<button type="button" class="chip ${h===hours?'selected':''}" data-hours="${h}">${h}h</button>`).join('')}</div><input type="hidden" id="wear-hours" value="${hours}"></div><p class="note">${type==='tampon'?'Change every 4–8 hours, sooner if needed. Never more than 8 hours.':'Follow your product’s wear-time instructions. Choose a shorter reminder if needed.'}${P[type].ml?' Emptying and reinserting starts a fresh timer.':''}</p><button class="btn full" type="submit">${P[type].internal?'It’s in. Start timer.':'It’s on. Start timer.'}</button><div id="form-error"></div></form>`);$('#add-form').onsubmit=e=>{e.preventDefault();try{const at=new Date($('#start-time').value).getTime(),h=Number($('#wear-hours').value);if(!Number.isFinite(at))throw Error('Choose a start time');transaction(()=>{M.add(state,type,h,at);const d=M.day();if(state.days[d])delete state.days[d].nothingTonight});closeSheet();page='now';render();toast(M.timer(state.active.find(x=>x.type===type)).overdue?'Logged — this product is already due for removal.':P[type].name+' timer started')}catch(e){$('#form-error').innerHTML=`<p class="error">${safe(e.message)}</p>`}}}
function localInput(ts){const d=new Date(ts);return `${M.day(ts)}T${String(d.getHours()).padStart(2,'0')}:${String(d.getMinutes()).padStart(2,'0')}`}
function openRemove(sessionId){const x=state.active.find(x=>x.id===sessionId);if(!x)return;let soak=null;photoPending=null;show(head(P[x.type].internal?'Coming out.':'Time for a change.')+`<form id="remove-form"><div class="product-intro">${art(x.type)}<div><h3>${P[x.type].name}</h3><span class="caption">In use for ${durationText(Date.now()-x.start)}</span></div></div>${P[x.type].ml?'<div class="field"><label for="collected">How much collected? <span class="muted">Optional</span></label><div class="row"><input id="collected" type="number" min="0" max="500" step="0.1" inputmode="decimal" placeholder="e.g. 15"><strong>ml</strong></div></div>':`<div class="field"><label>How soaked? <span class="muted">Optional</span></label><div class="soak">${['Dry','A little','Half','Mostly','Full'].map((s,i)=>`<button type="button" data-soak="${i}">${art(x.type,i)}${s}</button>`).join('')}</div></div>`}<label class="switch-row"><span class="label">Leaked?</span><input type="checkbox" id="leaked"></label><button type="button" class="photo-button" id="take-photo">▧ Add a private photo</button><div id="photo-area"></div><p class="note">Taken in the app. Kept out of your phone’s gallery.</p><div id="form-error"></div><button class="btn full" type="submit" data-action="remove">${P[x.type].internal?'It’s out':'Changed'} · save</button>${P[x.type].ml?'<button class="btn secondary full spaced" type="submit" data-action="reinsert">Emptied + back in</button>':`<button class="btn secondary full spaced" type="submit" data-action="replace">Save + ${P[x.type].internal?'put a fresh one in':'use a fresh one'}</button>`}<button class="btn outline full spaced" type="submit" data-action="nothing">☾ ${state.settings.cheeky?'Nothing tonight. Living dangerously.':'Nothing tonight'}</button></form>`);
body.querySelectorAll('[data-soak]').forEach(b=>b.onclick=()=>{soak=Number(b.dataset.soak);body.querySelectorAll('[data-soak]').forEach(c=>c.classList.toggle('selected',c===b))});$('#take-photo').onclick=()=>takePhoto(async data=>{try{photoPending={key:id(),data};$('#photo-area').innerHTML=`<img class="photo-preview" alt="Private product photo" src="${data}"><button type="button" class="plain-link" id="clear-photo">Remove photo</button>`;$('#clear-photo').onclick=()=>{photoPending=null;$('#photo-area').innerHTML=''}}catch(e){toast('Photo could not be added')}});
$('#remove-form').onsubmit=async e=>{e.preventDefault();const action=e.submitter?.dataset.action||'remove';if(action==='nothing'&&state.active.some(a=>a.id!==sessionId)){toast('Log your other product out first, or save this removal.');return}const buttons=[...body.querySelectorAll('button[type=submit]')],leaked=$('#leaked').checked;savingRemoval=true;buttons.forEach(b=>b.disabled=true);let photoKey=null;try{const ml=P[x.type].ml&&$('#collected').value!==''?Number($('#collected').value):null;if(ml!==null&&(!Number.isFinite(ml)||ml<0||ml>500))throw Error('Enter a valid amount');if(photoPending){photoKey=photoPending.key;await photoPut(photoKey,photoPending.data)}transaction(()=>{M.finish(state,sessionId,{ml,soak,leaked,photo:photoKey,reinserted:action==='reinsert'},action==='reinsert');if(action==='replace')M.add(state,x.type,x.hours);if(action==='nothing'){const d=M.day();state.days[d]={...state.days[d],nothingTonight:true}}});photoPending=null;savingRemoval=false;closeSheet();render();if(action==='nothing')nightMessage();else if(action==='remove'&&!state.active.length&&isNight())afterDark();else toast(action==='reinsert'?'Emptied. Back in. Timer reset.':action==='replace'?'Fresh one. Fresh timer.':'Logged. '+(state.settings.cheeky?'Excellent extraction.':'All done.'))}catch(e){savingRemoval=false;if(photoKey)await photoDelete(photoKey).catch(()=>{});$('#form-error').innerHTML=`<p class="error">${safe(e.message)}</p>`;buttons.forEach(b=>b.disabled=false)}}}
function isNight(){const h=new Date().getHours();return h>=20||h<6}
function afterDark(){show(head('And for tonight?')+`<div class="empty">${art('cup',0,true)}<p class="caption">Anything going in or on before bed?</p></div><button class="btn full spaced" data-choose>Pick some protection</button><button class="btn outline full spaced" data-nothing>☾ Nothing tonight</button>`)}
function nothingTonight(){if(state.active.length){toast('Log your current products out first.');return}transaction(()=>{const d=M.day();state.days[d]={...state.days[d],nothingTonight:true}});closeSheet();render();nightMessage()}
function nightMessage(){show(head(state.settings.cheeky?'Ooo. Risky business.':'Off duty tonight.')+`<section class="card night-card">${art('pants',0,true)}<h2>${state.settings.cheeky?'No backup. Brave.':'Nothing overnight'}</h2><p class="caption">${state.settings.cheeky?'The sheets wish you luck.':'Logged. No product timers are running.'}</p><button class="btn highlight full" data-close>${state.settings.cheeky?'I accept my fate':'Goodnight'}</button></section>`)}
function openSettings(){const s=setupStatus();show(head('Your rules.')+`<div class="product-intro">${art('cup')}<div><h3>Still In? <span class="caption">v0.2</span></h3><span class="caption">What's in. When it's out.</span></div></div><label class="switch-row"><span><strong>A little cheek?</strong><br><span class="caption">Playful comments. Serious reminders.</span></span><input type="checkbox" id="cheeky" ${state.settings.cheeky?'checked':''}></label><h3>Default reminders</h3><div class="settings-list">${Object.keys(P).map(k=>`<div class="row"><label for="hours-${k}">${P[k].name}</label><select id="hours-${k}" data-default="${k}">${[2,4,6,8,10,12].filter(h=>h<=P[k].max).map(h=>`<option value="${h}" ${(state.settings.hours[k]||P[k].hours)===h?'selected':''}>${h} hours</option>`).join('')}</select></div>`).join('')}</div><p class="note">These are reminder times, not guarantees of safe wear. Follow your product’s instructions. Changing a default won’t alter a running timer.</p>${native?`<h3 class="spaced">Phone reminders</h3><div class="setup-row row"><div>Notifications<br><span class="caption">${s.notifications?'Allowed ✓':'Not allowed'}</span></div><button class="btn secondary" data-permission="notifications">${s.notifications?'Settings':'Allow'}</button></div><div class="setup-row row"><div>Precise alarms<br><span class="caption">${s.exact?'Allowed ✓':'May be delayed'}</span></div><button class="btn secondary" data-permission="alarms">${s.exact?'Settings':'Allow'}</button></div><button class="btn outline full spaced" id="test-alarm">Test reminder in 10 seconds</button><p class="note">Check your alarm-channel sound in Android settings. Silent mode, Do Not Disturb, force-stopping the app, or a powered-off phone can affect alerts. Android may allow you to swipe away the countdown; the removal alarm remains scheduled.</p>`:`<div class="native-warning spaced"><strong>Phone alarms need the Android app.</strong><br>This web draft won’t remind you when it’s closed.<br><a class="btn secondary" href="still-in-0.2.apk" download>↓ Get the Android app</a></div>`}<h3 class="spaced">Your private stuff</h3><p class="caption">No login. No ads. No analytics. Your logs and photos stay on this device. Clearing app data or uninstalling removes them. Browser and APK logs are separate.</p><button class="btn outline full" id="export">Export logs + photos</button><p class="note">Only an export you request saves a copy outside the app. Keep that file private.</p><details><summary class="caption">Wear-time guidance</summary><p class="note">Tampons: change every 4–8 hours. Never more than 8 hours. Cup and disc instructions vary; check your brand’s stated limit. Overdue means past your chosen reminder, not a safe extension.</p><a class="plain-link" href="https://www.fda.gov/consumers/consumer-updates/facts-tampons-and-tampon-safety" target="_blank" rel="noopener">FDA tampon guidance</a></details>`);$('#cheeky').onchange=e=>doAction(()=>{transaction(()=>state.settings.cheeky=e.target.checked);render()});body.querySelectorAll('[data-default]').forEach(b=>b.onchange=()=>doAction(()=>transaction(()=>state.settings.hours[b.dataset.default]=Number(b.value))));$('#export').onclick=exportData;if(native)$('#test-alarm').onclick=()=>{StillAndroid.testAlarm();toast('Test set. Lock your phone and wait 10 seconds.')}}
function openSetup(){openSettings();body.querySelector('[data-permission]')?.scrollIntoView({behavior:'smooth',block:'center'})}
function bind(){document.querySelectorAll('nav [data-page]').forEach(b=>b.onclick=()=>{page=b.dataset.page;render();window.scrollTo(0,0)});$('#settings').onclick=openSettings;$('.brand').onclick=e=>{e.preventDefault();page='now';render()};bindCommon(main);main.querySelectorAll('[data-date]').forEach(b=>b.onclick=()=>{selectedDay=b.dataset.date;render()});main.querySelectorAll('[data-month]').forEach(b=>b.onclick=()=>{month=new Date(month.getFullYear(),month.getMonth()+Number(b.dataset.month),1);render()});$('[data-clear-flow]')?.addEventListener('click',()=>doAction(()=>{transaction(()=>delete state.days[selectedDay].flow);render()}));$('[data-save-note]')?.addEventListener('click',()=>doAction(()=>{const note=$('#day-note').value;transaction(()=>state.days[selectedDay]={...state.days[selectedDay],note});toast('Note saved')}));}
function bindCommon(root){root.querySelectorAll('[data-add]').forEach(b=>b.onclick=()=>openAdd(b.dataset.add));root.querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>openRemove(b.dataset.remove));root.querySelectorAll('[data-choose]').forEach(b=>b.onclick=choose);root.querySelectorAll('[data-nothing]').forEach(b=>b.onclick=()=>doAction(nothingTonight));root.querySelectorAll('[data-flow][data-day]').forEach(b=>b.onclick=()=>doAction(()=>{transaction(()=>{const note=$('#day-note');state.days[b.dataset.day]={...state.days[b.dataset.day],flow:b.dataset.flow,...(note?{note:note.value}:{})}});render();toast('Flow logged')}));root.querySelectorAll('[data-calendar]').forEach(b=>b.onclick=()=>{page='calendar';render()});root.querySelectorAll('[data-setup]').forEach(b=>b.onclick=openSetup);root.querySelectorAll('[data-view-photo]').forEach(b=>b.onclick=()=>viewPhoto(b.dataset.viewPhoto));root.querySelectorAll('[data-log]').forEach(b=>b.onclick=()=>logDetail(b.dataset.log));}
function bindSheet(){bindCommon(body);body.querySelectorAll('[data-close]').forEach(b=>b.onclick=closeSheet);body.querySelectorAll('[data-hours]').forEach(b=>b.onclick=()=>{body.querySelectorAll('[data-hours]').forEach(c=>c.classList.toggle('selected',c===b));$('#wear-hours').value=b.dataset.hours});body.querySelectorAll('[data-permission]').forEach(b=>b.onclick=()=>StillAndroid.permission(b.dataset.permission))}
function logDetail(logId){const x=state.history.find(a=>a.id===logId);if(!x)return;show(head(P[x.type].name+' receipt')+`<div class="product-intro">${art(x.type,x.soak??0)}<div><h3>${durationText(x.end-x.start)}</h3><span class="caption">${dateLabel(M.day(x.end))}</span></div></div><p class="caption">${new Date(x.start).toLocaleString()}<br>to ${new Date(x.end).toLocaleString()}</p><p>${x.ml!=null?`${x.ml} ml collected`:x.soak!=null?['Dry','A little soaked','Half soaked','Mostly soaked','Fully soaked'][x.soak]:'No amount logged'}${x.leaked?' · Leaked':''}</p>${x.photo?`<button class="btn secondary full" data-view-photo="${safe(x.photo)}">View private photo</button>`:''}<p class="note">${x.end>x.due?'Removed '+durationText(x.end-x.due)+' after your reminder time.':'Removed before your reminder time.'}</p><button class="btn danger full" id="delete-log">Delete this receipt</button><div id="delete-confirm"></div>`);$('#delete-log').onclick=()=>{$('#delete-confirm').innerHTML='<p class="caption">Delete this log and its photo? This cannot be undone.</p><button class="btn danger full" id="really-delete">Yes, delete</button>';$('#really-delete').onclick=()=>doAction(()=>{transaction(()=>state.history=state.history.filter(a=>a.id!==logId));if(x.photo)photoDelete(x.photo).catch(()=>{});closeSheet();render();toast('Receipt deleted')})}}
function photoDb(){return new Promise((resolve,reject)=>{const q=indexedDB.open('still-in-private-photos',1);q.onupgradeneeded=()=>q.result.createObjectStore('photos');q.onsuccess=()=>resolve(q.result);q.onerror=()=>reject(Error('Photo storage unavailable'))})}
async function photoOp(mode,fn){const db=await photoDb();return new Promise((resolve,reject)=>{const t=db.transaction('photos',mode);let result;const q=fn(t.objectStore('photos'));q.onsuccess=()=>result=q.result;t.oncomplete=()=>{db.close();resolve(result)};t.onerror=()=>{db.close();reject(Error('Could not save photo'))}})}
const photoPut=(k,d)=>photoOp('readwrite',s=>s.put(d,k)),photoGet=k=>photoOp('readonly',s=>s.get(k)),photoDelete=k=>photoOp('readwrite',s=>s.delete(k));
async function viewPhoto(key){try{const data=await photoGet(key);if(!data)throw Error('Photo no longer available');show(head('For your eyes only.')+`<img class="photo-preview" style="max-height:65vh" src="${data}" alt="Private product photo"><p class="note">Only stored inside this app.</p>`)}catch(e){toast(e.message)}}
function takePhoto(cb){photoCallback=cb;if(native){StillAndroid.takePhoto();return}browserCamera(cb)}
window.onNativePhoto=data=>{if(data&&photoCallback){const cb=photoCallback;photoCallback=null;cb(data)}else if(!data)toast('Photo cancelled')};
async function browserCamera(cb){try{stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:{ideal:'environment'},width:{ideal:1280}},audio:false});const overlay=document.createElement('div');overlay.id='camera-overlay';overlay.style.cssText='position:fixed;inset:0;background:#100d10;z-index:50;display:flex;flex-direction:column;padding:25px;gap:20px;color:white';overlay.innerHTML='<div class="row"><strong>Private camera</strong><button class="btn secondary" id="camera-cancel">Cancel</button></div><video id="camera-video" autoplay playsinline style="width:100%;min-height:0;flex:1;object-fit:contain"></video><button class="btn highlight" id="camera-capture">Take photo</button>';document.body.append(overlay);const video=$('#camera-video');video.srcObject=stream;const stop=()=>{stream?.getTracks().forEach(t=>t.stop());stream=null;overlay.remove()};$('#camera-cancel').onclick=stop;$('#camera-capture').onclick=()=>{if(!video.videoWidth)return;const c=document.createElement('canvas'),scale=Math.min(1,1000/video.videoWidth);c.width=video.videoWidth*scale;c.height=video.videoHeight*scale;c.getContext('2d').drawImage(video,0,0,c.width,c.height);const data=c.toDataURL('image/jpeg',.8);stop();cb(data)}}catch(e){toast('Camera unavailable or permission denied. No photo saved.')}}
async function exportData(){try{toast('Preparing your private export…');const photos={};for(const x of state.history){if(x.photo)photos[x.photo]=await photoGet(x.photo)}const data=JSON.stringify({app:'Still In?',exportedAt:new Date().toISOString(),state,photos},null,2);if(native){StillAndroid.exportData(data);return}const url=URL.createObjectURL(new Blob([data],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='still-in-private-export-'+M.day()+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}catch(e){toast('Could not export: '+e.message)}}
window.onNativeResume=()=>{if(native){try{state=M.validate(JSON.parse(StillAndroid.getState()));if(!sheet.open)render();else if($('#test-alarm'))openSettings()}catch(e){toast('Could not refresh saved state')}}};
sheet.addEventListener('cancel',e=>{if(savingRemoval){e.preventDefault();return}if(stream){stream.getTracks().forEach(t=>t.stop());stream=null}photoCallback=null});sheet.addEventListener('click',e=>{if(e.target===sheet){const r=sheet.getBoundingClientRect();if(e.clientY<r.top||e.clientX<r.left||e.clientX>r.right)closeSheet()}});document.addEventListener('visibilitychange',()=>{if(!document.hidden&&!sheet.open){if(M.day()!==selectedDay&&page==='now')selectedDay=M.day();render()}});render();
